import { Injectable } from '@nestjs/common'
import type { Prisma, Rental } from '../generated/prisma/client.js'
import { PrismaService } from '../prisma/prisma.service.js'

// relation query: joins each rental with its owner (owner_id), keeping only the owner's id and name
const withOwner = {
  owner: { select: { id: true, name: true } }, // gather only id and name from User
} satisfies Prisma.RentalInclude // RentalInclude comes from the Prisma schema

// type of a rental returned with its owner, generated by Prisma from the query above
export type RentalWithOwner = Prisma.RentalGetPayload<{
  include: typeof withOwner
}>

// data access layer: the only class that queries the RENTALS table
@Injectable()
export class RentalsRepository {
  constructor(private readonly prisma: PrismaService) {}

  findAll(): Promise<RentalWithOwner[]> {
    // "include" here is the prisma parameter for adding a field. it doesn't filter, it adds an owner field to each fetched rental
    return this.prisma.rental.findMany({ include: withOwner })
  }

  // findUnique: lookup by primary key, returns null when no rental has this id
  findById(id: number): Promise<RentalWithOwner | null> {
    return this.prisma.rental.findUnique({ where: { id }, include: withOwner })
  }

  // "Unchecked" input: the owner is given by its id (owner_id) instead of a nested relation
  create(data: Prisma.RentalUncheckedCreateInput): Promise<Rental> {
    return this.prisma.rental.create({ data })
  }
}
